def rd(rel): return pd.read_csv(OUT/rel)
def wr(df,rel): df.to_csv(OUT/rel,index=False,encoding='utf-8-sig',lineterminator='\n')
def doc(name,text): (ROOT/name).write_text(text.strip()+'\n',encoding='utf-8')
def rmse(x): x=np.asarray(x,float); return float(np.sqrt(np.mean(x*x))) if x.size else np.nan
def dist(x):
    x=np.asarray(x,float)
    return {'RMSE_mV':rmse(x),'P95_abs_error_mV':float(np.quantile(abs(x),.95)) if x.size else np.nan,'P99_abs_error_mV':float(np.quantile(abs(x),.99)) if x.size else np.nan,'max_abs_error_mV':float(abs(x).max()) if x.size else np.nan}
def m(x): return 'NOT_ESTIMABLE' if pd.isna(x) else f'{float(x):.6f}'

def cf_metrics(point, attribution, valid_error):
    event_key=valid_error[['fold','origin_row','target_row','horizon_step','error_type']].drop_duplicates()
    a=attribution.merge(event_key,on=['fold','origin_row','target_row','horizon_step'],how='left')
    scopes={
      'all_validation_common':a,
      'state_correct':a[a.error_type.isna()],
      'E1_predicted_mixed_true_nonmixed':a[a.error_type.eq('E1_predicted_mixed_true_nonmixed')],
      'E2_predicted_nonmixed_true_mixed':a[a.error_type.eq('E2_predicted_nonmixed_true_mixed')],
    }
    rows=[]
    for scope,d in scopes.items():
      keys=d[['fold','origin_row','target_row','horizon_step']].drop_duplicates()
      sub=point.merge(keys,on=['fold','origin_row','target_row','horizon_step'],how='inner')
      for cf,g in sub.groupby('cf'):
        row={'scope':scope,'cf':cf,'prediction_point_count':int(len(g)),'unique_target_count':int(g.target_row.nunique()),'independent_event_count':int(valid_error[valid_error.error_type.eq(scope)].shape[0]) if scope.startswith('E') else np.nan,**dist(g.error_mV)}
        if cf=='CF00' and len(d):
          row.update({'mean_Gain_q_mV2':float(d.Gain_q.mean()),'mean_Gain_cond_mV2':float(d.Gain_cond.mean()),'mean_Gain_both_mV2':float(d.Gain_both.mean()),'mean_Shapley_q_mV2':float(d.Shapley_q.mean()),'mean_Shapley_cond_mV2':float(d.Shapley_cond.mean()),'mean_Interaction_mV2':float(d.Interaction.mean())})
        rows.append(row)
    return pd.DataFrame(rows)

