    metrics={'baseline_rmse_mV':b,'train_event_counts':e_train.to_dict(),'validation_event_counts':e_val.to_dict(),'support_status':str(support.support_status),'support_segments':int(support.temporal_segments),'physical_residual_max_A':float(rawres.max()),'B_max_deviation_mV':bdev,'all_validation_cf_rmse_mV':overall.RMSE_mV.to_dict(),'fold1':r1.to_dict(),'fold3':r3.to_dict(),'normal_mean_gain_q_mV2':float(eventcf[(eventcf.scope=='state_correct')&(eventcf.cf=='CF00')].mean_Gain_q_mV2.iloc[0]),'normal_mean_gain_cond_mV2':float(eventcf[(eventcf.scope=='state_correct')&(eventcf.cf=='CF00')].mean_Gain_cond_mV2.iloc[0])}
