    for i,r in enumerate(caloverall.itertuples()): ax.annotate(r.fold,(r.mean_probability,r.observed_mixed_rate),xytext=(4,4),textcoords='offset points')
    ax.set(xlabel='Predicted mixed-state probability',ylabel='Observed mixed-state frequency',title='Train OOF probability calibration',xlim=(0,0.3),ylim=(0,0.3)); fig.tight_layout(); fig.savefig(OUT/'figures'/'train_oof_probability_calibration.png',bbox_inches='tight'); fig.savefig(OUT/'figures'/'train_oof_probability_calibration.pdf',bbox_inches='tight'); plt.close(fig)
